import{_ as e,o as a,c as s,a1 as l}from"./chunks/framework.BxsNGn3-.js";const o=JSON.parse('{"title":"我的大学时间轴","description":"","frontmatter":{},"headers":[],"relativePath":"guide/timeline.md","filePath":"guide/timeline.md"}'),d={name:"guide/timeline.md"};function t(c,i,n,v,r,p){return a(),s("div",null,[...i[0]||(i[0]=[l('<hr><h2 id="title-我的大学时间轴" tabindex="-1">title: 我的大学时间轴 <a class="header-anchor" href="#title-我的大学时间轴" aria-label="Permalink to &quot;title: 我的大学时间轴&quot;">​</a></h2><h1 id="我的大学时间轴" tabindex="-1">我的大学时间轴 <a class="header-anchor" href="#我的大学时间轴" aria-label="Permalink to &quot;我的大学时间轴&quot;">​</a></h1><p>从技术积累到实习、暑期实习和秋招，记录大学四年的重要规划。</p><div class="timeline"><div class="timeline-group early-group"><div class="timeline-dates"><div class="timeline-date"><b>2022.09</b><span>大一上</span></div><div class="timeline-date"><b>2023.01</b><span>大一寒假</span></div><div class="timeline-date"><b>2023.02</b><span>大一下</span></div><div class="timeline-date"><b>2023.07</b><span>大一暑假</span></div><div class="timeline-date"><b>2023.09</b><span>大二上</span></div></div><div class="timeline-cards"><article class="timeline-card early-card"><h2>技术沉淀</h2><p>以技术积累为主，打好基础，学习相关技能，也可以做一些小项目。</p><div class="timeline-note">阶段范围：大一上至大二上</div></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2024.01</b><span>大二寒假</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>继续积累</h2><p>继续做好技术积累，为后续实习和项目实践打基础。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2024.02</b><span>大二下</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>投递日常实习</h2><p>推荐在三、四月份开始投递日常实习，争取获得实习机会。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2024.07</b><span>大二暑假</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>把握日常实习机会</h2><p>八月底、九月初一定要把握机会投递日常实习。</p><div class="timeline-note">这个时间段的 HC（招聘名额）可能较多，要把握机会。</div></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2024.09</b><span>大三上</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>规划实习经历</h2><p>卷实习，每段实习可以按三个月规划。核心部门可以考虑多待一段时间。</p><p>日常实习较难接触核心部门，因此最好在暑期实习前卷出两段实习经历。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2025.01</b><span>大三寒假</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>为暑期实习做准备</h2><p>提前准备简历与面试，为接下来的暑期实习招聘做准备。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2025.02</b><span>大三下</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>投递暑期实习</h2><p>二月底、三月初，各厂会陆续开启暑期实习招聘，要尽早关注信息并投递。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2025.07</b><span>大三暑假</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>准备秋招</h2><p>七月底、八月初，各厂会陆续开启秋招面试和招聘流程，要尽早投递。</p><div class="timeline-note">举例：美团2025 届的秋招在 2024 年 7 月 29 日开启。具体时间以当年公告为准。</div></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2025.09</b><span>大四上</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>关注剩余秋招机会</h2><p>十二月份，部分公司仍可能有秋招机会，可以继续关注招聘信息。</p><p>如果已经拿到 offer，可以根据自身情况考虑 gap 一年；如果还没有拿到 offer，可以继续关注春招或考虑考研。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2026.01</b><span>大四寒假</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>做好毕业前的安排</h2><p>根据自己的求职或升学计划，继续准备后续安排。</p></article></div></div><div class="timeline-group"><div class="timeline-dates"><div class="timeline-date"><b>2026.02</b><span>大四下</span></div></div><div class="timeline-cards"><article class="timeline-card"><h2>关注春招</h2><p>二、三月份，各厂会陆续开启春招，这是毕业前最后一轮重要的招聘机会之一。</p></article></div></div><div class="timeline-group last-group"><div class="timeline-dates"><div class="timeline-date"><b>2026.06</b><span>毕业</span></div></div><div class="timeline-cards"><article class="timeline-card graduation-card"><h2>毕业</h2><p>完成大学阶段，开启下一段旅程。</p></article></div></div></div>',5)])])}const h=e(d,[["render",t]]);export{o as __pageData,h as default};
